INSERT INTO `galeri` VALUES (1,'Selamat datang di Monalisa Resto, perpaduan kenyamanan dan kelezatan.','assets/images/galeri/IMG_4222.jpg',1,'2026-05-12 03:47:49'),(2,'Ruang makan yang luas dan nyaman untuk berkumpul bersama keluarga.','assets/images/galeri/IMG_4223.jpg',2,'2026-05-12 03:47:49'),(3,'Suasana pagi yang cerah di sudut favorit Monalisa Resto.','assets/images/galeri/IMG_4224.jpg',3,'2026-05-12 03:47:49'),(4,'Berbagai pilihan camilan tradisional tersedia untuk melengkapi hidangan Anda.','assets/images/galeri/IMG_4226.jpg',4,'2026-05-12 03:47:49'),(5,'Sentuhan seni klasik yang menambah kehangatan suasana interior kami.','assets/images/galeri/IMG_4231.jpg',5,'2026-05-12 03:47:49'),(6,'Cahaya alami yang mempercantik setiap sudut ruang makan kami.','assets/images/galeri/IMG_4232.jpg',6,'2026-05-12 03:47:49');
